set-variable.value:
@{
      var mediaType = context.Request.Headers.GetValueOrDefault("Content-Type", "")
        .Split(";".ToCharArray())[0].Trim();
      var encoding = context.Request.Headers.GetValueOrDefault("Content-Encoding", "identity");
      if (!mediaType.Equals("application/json", StringComparison.OrdinalIgnoreCase) ||
          !encoding.Equals("identity", StringComparison.OrdinalIgnoreCase))
      {
        return 415;
      }
      if (context.Request.Body == null) { return 400; }
      var lengthHeader = context.Request.Headers.GetValueOrDefault("Content-Length", "");
      long length;
      if (lengthHeader != "" && (!Int64.TryParse(lengthHeader, out length) || length < 0))
      {
        return 400;
      }
      if (lengthHeader != "" && Int64.Parse(lengthHeader) > 1048576) { return 413; }
      return 0;
    }

@{
      var inputStatus = (int)context.Variables["pii-input-status"];
      if (inputStatus != 0) { return inputStatus.ToString() + "|unknown|0|0|none"; }
      var response = (IResponse)context.Variables["pii-response"];
      if (response == null) { return "503|unknown|0|0|none"; }
      if (response.StatusCode == 400 || response.StatusCode == 413 || response.StatusCode == 415)
      {
        return response.StatusCode.ToString() + "|unknown|0|0|none";
      }
      if (response.StatusCode != 200) { return "503|unknown|0|0|none"; }
        var result = JObject.Parse(response.Body.As<string>());
        var complete = result["inspectionComplete"];
        var allowed = result["allowed"];
        var version = result["ruleVersion"];
        var count = result["matchCount"];
        var duration = result["durationMs"];
        var matches = result["matches"] as JObject;
        if (complete == null || complete.Type != JTokenType.Boolean || !(bool)complete ||
            allowed == null || allowed.Type != JTokenType.Boolean ||
            version == null || version.Type != JTokenType.String ||
            !System.Text.RegularExpressions.Regex.IsMatch((string)version, "^[A-Za-z0-9._-]{1,64}$") ||
            count == null || count.Type != JTokenType.Integer ||
            duration == null || duration.Type != JTokenType.Integer || matches == null)
        {
          return "503|unknown|0|0|none";
        }
        var total = (long)count;
        var elapsed = (long)duration;
        if (total < 0 || total > Int32.MaxValue || elapsed < 0 || elapsed > 5000 ||
            matches.Count > 32 || (bool)allowed != (total == 0))
        {
          return "503|unknown|0|0|none";
        }
        long sum = 0;
        foreach (var match in matches.Properties())
        {
          if (!System.Text.RegularExpressions.Regex.IsMatch(match.Name, "^[A-Z][A-Z0-9_]{0,63}$") ||
              match.Value.Type != JTokenType.Integer || (long)match.Value < 1 ||
              (long)match.Value > Int32.MaxValue)
          {
            return "503|unknown|0|0|none";
          }
          sum += (long)match.Value;
        }
        if (sum != total) { return "503|unknown|0|0|none"; }
        return ((bool)allowed ? "200" : "403") + "|" + (string)version + "|" +
          total.ToString() + "|" + elapsed.ToString() + "|" +
          (matches.Count == 0 ? "none" : String.Join(",", matches.Properties().Select(p => p.Name)));
    }

return-response.set-body:
@{
            var status = (int)context.Variables["pii-status"];
            var code = status == 403 ? "PII_DETECTED" :
              status == 400 ? "INVALID_REQUEST" :
              status == 413 ? "REQUEST_TOO_LARGE" :
              status == 415 ? "UNSUPPORTED_CONTENT_TYPE" : "PII_INSPECTION_UNAVAILABLE";
            var error = new JObject(
              new JProperty("code", code),
              new JProperty("message", status == 403 ?
                "Request blocked by the PII policy. Remove personal data or secrets from the request context and try again." :
                "The request could not be safely processed."),
              new JProperty("requestId", context.RequestId.ToString()));
            if (status == 403)
            {
              var summary = ((string)context.Variables["pii-summary"]).Split("|".ToCharArray());
              error.Add(new JProperty("categories", new JArray(summary[4].Split(",".ToCharArray()))));
              error.Add(new JProperty("matchCount", Int32.Parse(summary[2])));
              error.Add(new JProperty("ruleVersion", summary[1]));
            }
            return new JObject(new JProperty("error", error)).ToString();
          }

inbound.set-body:
@{
      var body = context.Request.Body.As<JObject>(preserveContent: true);
      body["model"] = (string)context.Variables["deployment-name"];
      if (body["max_tokens"] != null)
      {
        if (body["max_completion_tokens"] == null)
        {
          body["max_completion_tokens"] = body["max_tokens"];
        }
        body.Remove("max_tokens");
      }
      return body.ToString();
    }

set-variable.value:
@{
          var body = (JObject)context.Variables["response-json"];
          var usage = body["usage"] as JObject;
          return usage == null || usage["prompt_tokens"] == null ? "0" : usage["prompt_tokens"].ToString();
        }

@{
          var body = (JObject)context.Variables["response-json"];
          var usage = body["usage"] as JObject;
          return usage == null || usage["completion_tokens"] == null ? "0" : usage["completion_tokens"].ToString();
        }

@{
          var body = (JObject)context.Variables["response-json"];
          var usage = body["usage"] as JObject;
          return usage == null || usage["total_tokens"] == null ? "0" : usage["total_tokens"].ToString();
        }
